    pub fn mi_stats_get_bin_size(bin: usize) -> usize;
    pub fn mi_theap_stats_get(theap: *mut mi_theap_t, stats: *mut mi_stats_t) -> bool;
    pub fn mi_theap_stats_merge_to_heap(theap: *mut mi_theap_t);
